package com.autocare.platform.order;
import com.autocare.platform.gateway.identity.*;
import com.autocare.platform.gateway.wechat.*;
import java.time.Instant;
import java.util.*;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.security.oauth2.jwt.*;
import org.springframework.test.context.bean.override.mockito.MockitoBean;
import org.springframework.test.web.servlet.MockMvc;
import org.springframework.http.MediaType;
import static org.mockito.Mockito.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@SpringBootTest(properties={"JWT_SECRET=test-only-secret-with-at-least-32-characters","WECHAT_APP_ID=test-app","INVITE_VERIFIED_IDENTITY_ENABLED=true"}) @AutoConfigureMockMvc class InvitationLoginHttpTest {
 @Autowired MockMvc mvc;@MockitoBean JwtDecoder decoder;@MockitoBean InvitationRegistration registration;@MockitoBean IdentityRepository identities;@MockitoBean AuthSessionRepository sessions;@MockitoBean AuthRateLimiter limits;@MockitoBean WechatCode2SessionClient wechat;@MockitoBean WechatPhoneClient phone;
 @Test void existingAccountGetsExplicitNoticeWithoutChangingOriginalLoginContract()throws Exception{String code="a".repeat(32);when(registration.registerForLogin("synthetic-openid",code,"UNKNOWN","test-app")).thenReturn(new InvitationRegistration.LoginResult(1,"EXISTING_ACCOUNT"));mvc.perform(post("/api/auth/wx-login").contentType(MediaType.APPLICATION_JSON).content("{\"code\":\"temporary\",\"role\":\"owner\",\"invite_code\":\""+code+"\"}")).andExpect(status().isOk()).andExpect(jsonPath("$.data.invitation_result").value("EXISTING_ACCOUNT"));}
 @BeforeEach void setup(){when(decoder.decode(anyString())).thenReturn(Jwt.withTokenValue("owner").header("alg","HS256").subject("1").claim("jti","session").claim("subject_type","user").claim("role","OWNER").claim("app_id","test-app").expiresAt(Instant.now().plusSeconds(600)).build());when(wechat.exchange("temporary")).thenReturn(new WechatSession("synthetic-openid",""));when(identities.ownerById(1)).thenReturn(Optional.of(new IdentityRepository.Owner(1,null,1,false)));when(identities.ownerOpenidById(1)).thenReturn(Optional.of("synthetic-openid"));when(phone.exchange("phone-code","synthetic-openid")).thenReturn("13800138000");}
 @Test void officialExchangeCarriesOpaqueCodeToAtomicRegistration()throws Exception{String code="a".repeat(32);when(wechat.officialEndpoint()).thenReturn(true);when(registration.registerForLogin("synthetic-openid",code,"VERIFIED_WECHAT","test-app")).thenReturn(new InvitationRegistration.LoginResult(1,"ATTRIBUTED"));mvc.perform(post("/api/auth/wx-login").contentType(MediaType.APPLICATION_JSON).content("{\"code\":\"temporary\",\"role\":\"owner\",\"invite_code\":\""+code+"\"}")).andExpect(status().isOk()).andExpect(jsonPath("$.data.user.id").value(1));verify(registration).registerForLogin("synthetic-openid",code,"VERIFIED_WECHAT","test-app");verify(identities,never()).createOwnerOrRead(anyString());}
 @Test void nonofficialExchangeCannotCreateFormalEvidence()throws Exception{when(registration.registerForLogin("synthetic-openid",null,"UNKNOWN","test-app")).thenReturn(new InvitationRegistration.LoginResult(1,"ATTRIBUTED"));mvc.perform(post("/api/auth/wx-login").contentType(MediaType.APPLICATION_JSON).content("{\"code\":\"temporary\",\"role\":\"owner\"}")).andExpect(status().isOk());verify(registration).registerForLogin("synthetic-openid",null,"UNKNOWN","test-app");}
 @Test void proofFlagsMalformedOrTechnicianCodesNeverReachExchange()throws Exception{for(String raw:List.of("{\"code\":\"temporary\",\"role\":\"owner\",\"new_user\":true}","{\"code\":\"temporary\",\"role\":\"owner\",\"verified\":true}","{\"code\":\"temporary\",\"role\":\"owner\",\"invite_code\":null}","{\"code\":\"temporary\",\"role\":\"technician\",\"invite_code\":\""+"a".repeat(32)+"\"}"))mvc.perform(post("/api/auth/wx-login").contentType(MediaType.APPLICATION_JSON).content(raw)).andExpect(status().isBadRequest());verify(wechat,never()).exchange(anyString());verifyNoInteractions(registration);}
 @Test void phoneProofOnlyComesFromOfficialServerAdapter()throws Exception{when(phone.officialEndpoints()).thenReturn(true);mvc.perform(post("/api/auth/phone/bind").header("Authorization","Bearer owner").contentType(MediaType.APPLICATION_JSON).content("{\"code\":\"phone-code\"}")).andExpect(status().isOk()).andExpect(jsonPath("$.data.phone_bound").value(true));verify(registration).bindPhone(any(com.autocare.platform.vehicle.VehicleOwner.class),eq("13800138000"),eq("test-app"),eq(true));when(phone.officialEndpoints()).thenReturn(false);mvc.perform(post("/api/auth/phone/bind").header("Authorization","Bearer owner").contentType(MediaType.APPLICATION_JSON).content("{\"code\":\"phone-code\"}")).andExpect(status().isOk());verify(registration).bindPhone(any(com.autocare.platform.vehicle.VehicleOwner.class),eq("13800138000"),eq("test-app"),eq(false));}
 @Test void phoneBindingRejectsClientProofDuplicateAndTrailingJson()throws Exception{for(String raw:List.of("{\"code\":\"phone-code\",\"verified\":true}","{\"code\":\"phone-code\",\"code\":\"other\"}","{\"code\":\"phone-code\"}{}"))mvc.perform(post("/api/auth/phone/bind").header("Authorization","Bearer owner").contentType(MediaType.APPLICATION_JSON).content(raw)).andExpect(status().isBadRequest());verify(phone,never()).exchange(anyString(),anyString());verifyNoInteractions(registration);}
}
